"""Auto-generated by s1-ready. Fine-tune on a ShareGPT-style ({conversations: [...]}) export.

Use case: Decide whether an SMS message is spam

Run this in your TRAINING environment (where unsloth + trl + a GPU live):
    pip install unsloth trl datasets
    python sms_spam.jsonl.train.py

Edit MODEL_NAME below before running.
"""

from datasets import load_dataset
from unsloth import FastLanguageModel
from unsloth.chat_templates import standardize_sharegpt
from trl import SFTTrainer, SFTConfig

# TODO: set your base model.
MODEL_NAME = "unsloth/llama-3.1-8b-instruct-bnb-4bit"
DATA_FILE = "sms_spam.jsonl"
MAX_SEQ_LEN = 2048

model, tokenizer = FastLanguageModel.from_pretrained(
    model_name=MODEL_NAME,
    max_seq_length=MAX_SEQ_LEN,
    load_in_4bit=True,
)
model = FastLanguageModel.get_peft_model(
    model, r=16, lora_alpha=16, lora_dropout=0,
    target_modules=["q_proj", "k_proj", "v_proj", "o_proj",
                    "gate_proj", "up_proj", "down_proj"],
)

dataset = load_dataset("json", data_files=DATA_FILE, split="train")
# Normalize the ShareGPT rows, then render with the model's chat template.
dataset = standardize_sharegpt(dataset)


def formatting_prompts_func(examples):
    texts = [
        tokenizer.apply_chat_template(
            convo, tokenize=False, add_generation_prompt=False
        )
        for convo in examples["conversations"]
    ]
    return {"text": texts}


dataset = dataset.map(formatting_prompts_func, batched=True)

# Sanity-check one rendered row before training.
print("=== sample rendered row ===")
print(dataset[0]["text"])

trainer = SFTTrainer(
    model=model,
    tokenizer=tokenizer,
    train_dataset=dataset,
    args=SFTConfig(
        dataset_text_field="text",
        max_seq_length=MAX_SEQ_LEN,
        per_device_train_batch_size=2,
        gradient_accumulation_steps=4,
        warmup_steps=5,
        num_train_epochs=1,
        learning_rate=2e-4,
        logging_steps=1,
        output_dir="outputs",
    ),
)
trainer.train()
